<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\Holder\UserAcceptedTermsOfUseConditionsAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAcceptedTermsOfUseConditionsAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAcceptedTermsOfUseConditionsAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getConditions returns null on a freshly created holder.
     */
    public function testConditionsNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermsOfUseConditionsAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isConditionsAssigned());
        $this->assertNull($holder->getConditions());
    }
}
class ImplWithUserAcceptedTermsOfUseConditionsAttributeHolderUnitTest
{
    use UserAcceptedTermsOfUseConditionsAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedConditionsRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultConditions();
    }
}
